def transform(grid):
    out = [row[:] for row in grid]
    # Special cells on the horizontal bar project a vertical column of 1s upward;
    # the special cell is repeated at the tip.
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (2, 8):
                height = 4 if value == 2 else 3
                for d in range(1, height + 1):
                    rr = r - d
                    if rr >= 0:
                        out[rr][c] = value if d == height else 1
    return out
